import { setupWorker } from 'msw/browser';
import * as generatedMocks from '@/api/generated/index.msw';

/**
 * Request mocking for stories (#333). Every handler is generated by Orval from `api.json`
 * (`npm run orval:file`); stories never hand-write one for a generated endpoint.
 *
 * The generated handlers are the worker's initial handlers, so they survive the addon's reset
 * between stories: any data-fetching component renders generated data unless a story overrides
 * an endpoint in `beforeEach({ msw })`.
 */
const generatedHandlers = Object.values(generatedMocks).flatMap((mocksForTag) => mocksForTag());

let unhandled: string[] = [];

/** Starts the worker for `mswLoader`. API requests without a handler are recorded, then fail the story. */
export const startStoryWorker = async () => {
	const worker = setupWorker(...generatedHandlers);

	await worker.start({
		quiet: true,
		onUnhandledRequest: (request, print) => {
			const url = new URL(request.url);

			// Only API calls count; Vite modules, fonts and images pass through untouched.
			if (url.pathname.includes('/api/')) {
				unhandled.push(`${request.method} ${url.pathname}`);
				print.error();
			}
		},
	});

	return worker;
};

/** The API requests no handler answered since the last call, oldest first. */
export const takeUnhandledRequests = () => {
	const requests = unhandled;
	unhandled = [];

	return requests;
};
